public typealias WireBytes = [UInt8]

/// Why a document or an operation could not be read or written: the domain and code
/// upstream's Foundation bindings put in an `NSError`, and the same message.
public struct RemoteComposeWireError: Error, Equatable, CustomStringConvertible {
    public let domain: String
    public let code: Int
    public let message: String

    public init(domain: String, code: Int, message: String) {
        self.domain = domain
        self.code = code
        self.message = message
    }

    public var description: String { "\(domain) \(code): \(message)" }
}

/// [bytes] as UTF-8 text, or nil when they are not valid UTF-8 (where Foundation's
/// `String(data:encoding:)` fails, rather than repairing them as `String(decoding:)` does).
func wireDecodeUTF8(_ bytes: WireBytes) -> String? {
    let text = String(decoding: bytes, as: UTF8.self)
    return text.utf8.elementsEqual(bytes) ? text : nil
}


