public enum IdEncoding {
    public static let NAN_PREFIX: Int32 = -8388608
    public static let PAYLOAD_MASK: Int32 = 4194303
    public static let START_ID: Int32 = 42
    public static let REGION_MASK: Int32 = 3145728
    public static let REGION_SUB_ID_MASK: Int32 = 1048575
    public static let REGION_SYSTEM: Int32 = 0
    public static let REGION_VARIABLE: Int32 = 1048576
    public static let REGION_ARRAY: Int32 = 2097152
    public static let REGION_OPERATION: Int32 = 3145728
    public static let START_ARRAY_ID: Int32 = 2097194
    public static let LONG_ID_OFFSET: Int64 = 4294967296
    public static let PTR_DEREFERENCE: Int32 = 1073741824
    public static let VALUE_MASK: Int32 = 65535
    public static let MACRO_LOCAL_START_ID: Int32 = 16384
    public static let MACRO_LOCAL_END_ID: Int32 = 20479
    public static func isNanBits(_ bits: Int32) -> Bool { (bits & NAN_PREFIX) == NAN_PREFIX && (bits & PAYLOAD_MASK) != 0 }
    public static func idFromNanBits(_ bits: Int32) -> Int32 { isNanBits(bits) ? (bits & PAYLOAD_MASK) : -1 }
    public static func asNanBits(_ id: Int32) -> Int32 { (id & PAYLOAD_MASK) | NAN_PREFIX }
    public static func isDereferenced(_ raw: Int32) -> Bool { (raw & PTR_DEREFERENCE) != 0 }
    public static func directId(_ raw: Int32) -> Int32? { isDereferenced(raw) ? nil : (raw & VALUE_MASK) }
    public static func pointerId(_ raw: Int32) -> Int32? { isDereferenced(raw) ? (raw & VALUE_MASK) : nil }
}

