    ///   - intUniforms: Integer uniform arrays
    ///   - bitmapUniforms: Bitmap sampler uniforms
    public init(shaderId: Int32 = 0, shaderTextId: Int32 = 0, floatUniforms: [ShaderFloatUniform] = [], intUniforms: [ShaderIntUniform] = [], bitmapUniforms: [ShaderBitmapUniform] = []) {
        self.shaderId = shaderId
        self.shaderTextId = shaderTextId
