/// Defines a reusable template pattern with parameter IDs
public struct PatternDefine: RemoteOperation, Equatable {
    public let opCode: OpCode = .patternDefine

    /// The ID of the pattern template
    public var id: Int32
    /// Parameter variable IDs
    public var paramIds: [Int32]
    /// Serialized pattern body operations
    public var bodyBytes: WireBytes

    /// Creates a new [PatternDefine] operation.
    /// - Parameters:
    ///   - id: The ID of the pattern template
    ///   - paramIds: Parameter variable IDs
    ///   - bodyBytes: Serialized pattern body operations
    public init(id: Int32 = 0, paramIds: [Int32] = [], bodyBytes: WireBytes = WireBytes()) {
        self.id = id
        self.paramIds = paramIds
        self.bodyBytes = bodyBytes
    }

    /// Reads and decodes a [PatternDefine] from the wire buffer.
    public static func read(from buffer: inout WireBuffer) throws -> PatternDefine {
        let id = try buffer.readInt()
        let _paramIdsCount = Int(try buffer.readInt())
        guard _paramIdsCount >= 0 else {
            throw RemoteComposeWireError(domain: "PatternDefine", code: 1, message: "Invalid negative array length")
        }
        guard _paramIdsCount <= buffer.remaining / 4 else {
            throw RemoteComposeWireError(domain: "PatternDefine", code: 1, message: "Array length exceeds remaining buffer")
        }
        var paramIds = [Int32]()
        paramIds.reserveCapacity(Swift.min(_paramIdsCount, 4096))
        for _ in 0..<_paramIdsCount {
            paramIds.append(try buffer.readInt())
        }
        let bodyBytes = try buffer.readBuffer()
        return PatternDefine(id: id, paramIds: paramIds, bodyBytes: bodyBytes)
    }

    /// Serializes this operation to the wire buffer.
    public func write(to buffer: inout WireBuffer) throws {
        buffer.writeByte(opCode.rawValue)
        buffer.writeInt(id)
        buffer.writeInt(Int32(paramIds.count))
        for item in paramIds {
            buffer.writeInt(item)
        }
        buffer.writeBuffer(bodyBytes)
    }
}

